# Different approach - look at the assistant message before each error
# Get the tool call content (args) from toolUse blocks that resulted in errors
for f in $(find .state/sessions .state/sessions/history -maxdepth 3 -name "session.jsonl" 2>/dev/null); do
  node -e "
    const fs = require('fs');
    const lines = fs.readFileSync('$f','utf8').trim().split('\n');
    for (let i = 0; i < lines.length; i++) {
      try {
        const msg = JSON.parse(lines[i]);
        if (msg.isError && msg.toolName === 'bash') {
          // find the matching toolUse
          for (let j = i-1; j >= 0; j--) {
            try {
              const prev = JSON.parse(lines[j]);
              if (prev.role === 'assistant' && prev.content) {
                for (const block of prev.content) {
                  if (block.type === 'tool_use' && block.id === msg.toolCallId) {
                    const cmd = block.input?.command || JSON.stringify(block.input);
                    const errText = msg.content?.map(c=>c.text).join('').slice(0,100) || '';
                    console.log(cmd.slice(0,150) + ' ||| ERROR: ' + errText);
                  }
                }
              }
            } catch {}
          }
        }
      } catch {}
    }
  " 2>/dev/null
